      ]
    },
    {
      "trackId": "service",
      "name": "Service",
      "steps": [
        { "stepId": "lay-table", "name": "Lay table", "task": "table", "duration": { "type": "fixed", "seconds": 300 }, "startTrigger": { "type": "afterStep", "stepId": "toast-bread" }, "metadata": { "sourceSpan": { "quote": "Lay four places", "occurrence": 1 }, "inferred": false } },
